select id, 'levels', '{"levels":[{"level":3,"marks":[5,6],"descriptor":"Factors affecting both thinking and braking distance explained clearly, with a clear explanation of the effect of speed linked to kinetic energy or work done."},{"level":2,"marks":[3,4],"descriptor":"Factors affecting thinking and/or braking distance identified, with some explanation."},{"level":1,"marks":[1,2],"descriptor":"One or two factors named with little or no explanation."}],"indicative":["Thinking distance increases if the driver''s reaction time is longer: tiredness, alcohol, drugs, distractions such as a phone","Braking distance increases with wet or icy roads (less friction between tyres and road)","Worn tyres or worn brakes increase braking distance","A heavier car (more mass) has a longer braking distance","At higher speed the car travels further during the reaction time, so thinking distance increases in proportion to speed","Kinetic energy depends on speed squared, so doubling speed means four times the work done by the brakes, so braking distance increases a lot","Large decelerations can cause brakes to overheat or the car to skid"],"guidance":"Level 3 needs both thinking and braking distance and a reason for the effect of speed."}'::jsonb, '{"AO1":3,"AO2":3}'::jsonb, 0 from q;

