select id, 'levels', '{"levels":[{"level":3,"marks":[5,6],"descriptor":"A clear explanation of how an alternating current in the primary induces a p.d. in the secondary, and a clear explanation of why high p.d. reduces energy losses, including the step-down transformers."},{"level":2,"marks":[3,4],"descriptor":"Some explanation of how a transformer works or of why high p.d. is used, with some correct physics."},{"level":1,"marks":[1,2],"descriptor":"Simple statements about transformers or the National Grid."}],"indicative":["A transformer has primary and secondary coils wound on an iron core","An alternating current in the primary coil produces a changing magnetic field in the iron core","The changing field induces an alternating potential difference across the secondary coil","A step-up transformer has more turns on the secondary than the primary","For the same power, a higher p.d. means a lower current (P = VI)","Lower current means less heating of the cables, so less energy is wasted (P = I²R)","Step-down transformers reduce the p.d. to a safe 230 V for homes","Transformers only work with alternating current"],"guidance":"Level 3 needs both parts of the question."}'::jsonb, '{"AO1":4,"AO2":2}'::jsonb, 0 from q;

