insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'points', '{"max":4,"points":["Opportunity cost is the next best alternative given up when a choice is made","It arises because resources are scarce / limited while wants are unlimited, so choices have to be made","Applied: if the government builds the hospital, the opportunity cost is the roads (or the benefits of the roads) it can no longer build","Applied: the £2 billion can only be spent once, so spending it on one means sacrificing the other"],"guidance":"Two marks for knowledge and two for applying it to the hospital and roads. ''The cost of something'' alone does not define opportunity cost."}'::jsonb, '{"AO1":2,"AO2":2}'::jsonb, 0 from q;

with v(qt) as (select 'A poor harvest in Brazil has reduced the world supply of coffee beans. At the same time, coffee has become more popular in China.

Analyse the likely effects of these two changes on the equilibrium price and quantity of coffee beans. You may describe a supply and demand diagram in words.'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
