insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":3,"marks":[5,6],"descriptor":"Clear chains of reasoning for both changes, correctly identifying the effect on price and a reasoned conclusion about quantity (which depends on the relative size of the shifts)."},{"level":2,"marks":[3,4],"descriptor":"Correct analysis of one change, or both changes with limited development."},{"level":1,"marks":[1,2],"descriptor":"Simple statements, e.g. price will rise, with little explanation."}],"indicative":["The poor harvest shifts the supply curve to the left (decrease in supply)","The decrease in supply causes excess demand at the old price, so the price rises and quantity falls","Greater popularity in China shifts the demand curve to the right (increase in demand)","The increase in demand causes excess demand, so the price rises and quantity rises","Both changes push the price up, so the equilibrium price will definitely rise","The effect on quantity is uncertain: it depends on whether the supply shift or the demand shift is bigger","Price acts as a rationing signal: higher price reduces quantity demanded and encourages other producers to supply"],"guidance":"Shifts must be distinguished from movements along a curve for Level 3. Credit a clearly described diagram."}'::jsonb, '{"AO2":2,"AO3":4}'::jsonb, 0 from q;

