insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":3,"marks":[7,9],"descriptor":"Good knowledge applied well; developed chains of reasoning showing both costs and benefits of monopoly; a supported judgement that answers ''always''."},{"level":2,"marks":[4,6],"descriptor":"Reasonable knowledge with some analysis of costs and benefits; evaluation is limited or one-sided."},{"level":1,"marks":[1,3],"descriptor":"Limited knowledge with simple points; little or no analysis or evaluation."}],"indicative":["A monopoly is a single seller with a large share of the market (legal definition 25%+)","Monopolies may charge higher prices because consumers have no alternative","Less choice and less incentive to improve quality or customer service","Possible inefficiency because there is no competitive pressure to keep costs down","But monopolies can gain economies of scale, which could lower prices","Supernormal profits may be invested in research and development and innovation","Natural monopolies (e.g. rail track, water) may be more efficient with one firm","Government regulation (e.g. the Competition and Markets Authority, price caps) can protect consumers","Judgement: depends on regulation, barriers to entry and how the firm uses its profits, so not always bad"],"guidance":"Level 3 requires a justified conclusion that addresses ''always''."}'::jsonb, '{"AO1":1,"AO2":2,"AO3":3,"AO4":3}'::jsonb, 0 from q;

