select id, 'levels', '{"levels":[{"level":3,"marks":[7,9],"descriptor":"Good knowledge applied well; developed chains of reasoning on how spending affects unemployment and its drawbacks; a supported judgement."},{"level":2,"marks":[4,6],"descriptor":"Reasonable knowledge with some analysis; evaluation limited or one-sided."},{"level":1,"marks":[1,3],"descriptor":"Limited knowledge with simple points; little analysis or evaluation."}],"indicative":["Increasing government spending is expansionary fiscal policy","Spending on infrastructure, e.g. building projects, creates jobs directly","It increases total demand in the economy, so firms need more workers (derived demand for labour)","There may be a multiplier effect as newly employed workers spend their incomes","But it increases the budget deficit and national debt, which must be repaid with interest or higher taxes later","It may take time for projects to start (time lags)","It could cause inflation if the economy is near full capacity","It may not help structural unemployment if the jobs created don''t match workers'' skills","Alternatives: cut interest rates (monetary policy), training schemes (supply-side), tax cuts","Judgement: depends on the type of unemployment, size of existing debt and how the money is spent"],"guidance":"Level 3 requires a justified conclusion."}'::jsonb, '{"AO1":1,"AO2":2,"AO3":3,"AO4":3}'::jsonb, 0 from q;

