with v(qt) as (select 'Bean There is a coffee van. Its fixed costs are £1500 per month. Each coffee sells for £3.00 and has variable costs of £1.00.

(a) Calculate the number of coffees Bean There must sell each month to break even.
(b) Last month it sold 1000 coffees. Calculate its margin of safety.

Show your working.'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
