  where s.name = 'Business' and t.name = 'Finance' and st.name = 'Break-even'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'points', '{"max":4,"points":["Contribution per unit = £3.00 − £1.00 = £2.00","Break-even = fixed costs ÷ contribution = 1500 ÷ 2","= 750 coffees","Margin of safety = 1000 − 750 = 250 coffees"],"guidance":"Correct answers with no working score full marks. Allow error carried forward from a wrong break-even for the margin of safety."}'::jsonb, '{"AO2":4}'::jsonb, 0 from q;

