with v(qt) as (select 'Read this sentence from a story:

"The city was a sleeping animal, its streetlights blinking like tired eyes, its traffic a low growl that never quite stopped."

Identify one technique the writer uses and analyse the effect it creates. Use a quotation and a subject term in your answer.'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'analyse', 4, 'foundation', 'AQA', 'L1.2', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Language' and t.name = 'Language Techniques and Terminology' and st.name = 'Figurative language'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'points', '{"max":4,"points":["Identifies a technique correctly, e.g. metaphor (''The city was a sleeping animal''), simile (''blinking like tired eyes'') or personification (''a low growl'')","Supports with a relevant quotation","Explains the meaning: the city is presented as alive, resting but not fully asleep","Analyses the effect on the reader, e.g. creates a sense of quiet threat or unease, as if the city could wake at any moment; or makes the city feel tired and worn out","Comments on a specific word, e.g. ''growl'' suggests danger; ''never quite stopped'' suggests restlessness"],"guidance":"Max 4. ''It makes the reader want to read on'' or ''it creates a picture in your head'' is too general to score the analysis marks."}'::jsonb, '{"AO2":4}'::jsonb, 0 from q;

with v(qt) as (select 'Read this extract:

"She ran. Past the bins, past the broken gate, past the dog that barked and barked and would not stop barking, down the alley where the light gave up and the dark took over. Then she stopped. Silence."

Analyse how the writer uses sentence forms to create tension.'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'analyse', 4, 'foundation', 'AQA', 'L2.2', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Language' and t.name = 'Structure and Sentence Forms' and st.name = 'Sentence forms and punctuation for effect'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'points', '{"max":4,"points":["Short simple sentence ''She ran.'' is abrupt, creating urgency at the start","Long sentence with a list / repetition of ''past'' builds pace and shows how far and fast she is running","Repetition of ''barked and barked'' makes the noise feel relentless and panicky","Contrast between the long sentence and the short ''Then she stopped.'' creates a sudden halt","One-word minor sentence ''Silence.'' creates suspense: the reader waits to find out what happens next","Uses accurate terms (simple sentence, minor sentence, complex/compound sentence, listing, repetition)"],"guidance":"Max 4. Feature-spotting without explaining the effect scores at most 1."}'::jsonb, '{"AO2":4}'::jsonb, 0 from q;

with v(qt) as (select 'This extract is from the opening of a short story written for this question.

The storm arrived before anyone was ready for it. All afternoon the sky had been a bruise, swollen and purple over the harbour, and the fishermen had muttered and dragged their boats higher up the shingle. Then, at six o''clock, the wind tore loose. It screamed down the narrow streets, rattling every shutter like a fist on a door. Rain came sideways, hard as gravel. Old Mrs Penrose, who had seen sixty winters on this coast, stood at her window and watched the sea rear up and hurl itself against the wall, again and again, as though it had a grudge against the town and meant to settle it tonight.

How does the writer use language here to describe the storm?

You could include the writer''s choice of:
• words and phrases
• language features and techniques
• sentence forms.

[8 marks]'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'analyse', 8, 'higher', 'AQA', 'L3.1', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Language' and t.name = 'Paper 1 Reading: Creative Reading' and st.name = 'Questions 1 and 2: retrieval and language'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":4,"marks":[7,8],"descriptor":"Perceptive, detailed analysis of the effects of language; judicious, well-chosen quotations; sophisticated and accurate use of subject terminology."},{"level":3,"marks":[5,6],"descriptor":"Clear explanation of the effects of language; relevant quotations; clear and accurate use of subject terminology."},{"level":2,"marks":[3,4],"descriptor":"Some attempt to comment on the effect of language; some appropriate textual detail; some use of subject terminology, not always accurately."},{"level":1,"marks":[1,2],"descriptor":"Simple comments on the effect of language; simple references; simple mention of subject terminology."}],"indicative":["Metaphor ''the sky had been a bruise, swollen and purple'' suggests pain and injury; the storm feels like an attack waiting to happen","Personification ''the wind tore loose. It screamed'' presents the storm as a violent, uncontrollable creature","Simile ''like a fist on a door'' suggests aggression and threat, as if something is trying to get in","Simile ''hard as gravel'' makes the rain painful and physical","Personification of the sea: ''rear up and hurl itself'', ''had a grudge against the town'' makes nature seem vengeful and deliberate","Short sentence ''Then, at six o''clock, the wind tore loose.'' marks the sudden start of the storm","Repetition ''again and again'' shows the relentless force of the sea","Contrast with Mrs Penrose''s calm, experienced watching makes the storm seem even more extreme"],"guidance":"Focus is on language only; comments on structure are not credited. Level 3 and above need explanation of effects, not just identification."}'::jsonb, '{"AO2":8}'::jsonb, 0 from q;

with v(qt) as (select 'This is the whole of a very short story written for this question.

The station was empty except for Lena. She checked the board for the third time: the last train, delayed. She sat on the cold bench, pulled her coat tighter and counted the pigeons picking at a crust by the bin. Seven. Then six, as one flapped away.

Across the tracks a light flickered on in the signal box. A shape moved behind the dirty glass. Lena told herself it was the signalman, of course it was, and looked back at her phone. No signal.

Footsteps. Slow, unhurried, on the metal bridge above the platform. They stopped directly over her head.

Lena did not look up.

The board above her clicked and changed: CANCELLED.

How has the writer structured the text to interest you as a reader?

You could write about:
• what the writer focuses your attention on at the beginning
• how and why the writer changes this focus as the text develops
• any other structural features that interest you.

[8 marks]'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'analyse', 8, 'higher', 'AQA', 'L3.2', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Language' and t.name = 'Paper 1 Reading: Creative Reading' and st.name = 'Question 3: structure'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":4,"marks":[7,8],"descriptor":"Perceptive, detailed analysis of the effects of structural features; judicious examples; sophisticated and accurate subject terminology."},{"level":3,"marks":[5,6],"descriptor":"Clear explanation of the effects of structural features; relevant examples; clear and accurate terminology."},{"level":2,"marks":[3,4],"descriptor":"Some attempt to comment on structural features; some appropriate examples; some terminology."},{"level":1,"marks":[1,2],"descriptor":"Simple comments on structure; simple references."}],"indicative":["Opens with a focus on setting and isolation: ''The station was empty except for Lena'', establishing her vulnerability","Slow, mundane details at the start (counting pigeons) create a calm, ordinary mood that is later disrupted","Shift of focus outward to the signal box and the shape behind the glass introduces a possible threat","Her phone having ''No signal'' cuts her off and increases tension","One-word paragraph ''Footsteps.'' marks a turning point and sharpens the focus to sound","Single-line paragraph ''Lena did not look up.'' slows the pace and creates suspense","The ending returns to the departure board from the opening (cyclical structure), but now ''CANCELLED'', trapping her","Open, unresolved ending leaves the reader uncertain and uneasy"],"guidance":"Focus is on structure; comments only on individual words score at most Level 1."}'::jsonb, '{"AO2":8}'::jsonb, 0 from q;

with v(qt) as (select 'This extract is from a story written for this question. Tom, aged twelve, is starting at a new school.

The corridor smelled of floor polish and somebody else''s lunch. Tom kept his eyes on the lino, on the black scuffs left by a thousand trainers that weren''t his. Around him the noise rose and broke like a wave: shrieks, laughter, a locker slammed so hard it rang. Everyone seemed to know exactly where they were going.

He checked the timetable in his hand. Room 14. The numbers on the doors went 9, 10, 11 and then, for no reason at all, 22.

"You lost?" A girl with a plaster on her chin was looking at him. Not unkindly. Just looking.

Tom opened his mouth. Nothing came out. His face burned.

"Fourteen''s upstairs," she said. "Everyone gets lost. I cried on my first day. In the toilets. Don''t tell anyone." She grinned, and the corridor seemed, very slightly, to shrink.

A student said: "In this part of the story, the writer makes you really feel Tom''s nervousness, and then shows how one small act of kindness changes everything."

To what extent do you agree?

In your response, you could:
• consider your own impressions of Tom
• evaluate how the writer creates these impressions
• support your response with references to the text.

[20 marks]'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'evaluate', 20, 'higher', 'AQA', 'L3.3', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Language' and t.name = 'Paper 1 Reading: Creative Reading' and st.name = 'Question 4: evaluation'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":4,"marks":[16,20],"descriptor":"Critical, detailed evaluation of the effect on the reader; shows perceptive understanding of the writer''s methods; convincing, critical response to the statement; judicious, wide-ranging references."},{"level":3,"marks":[11,15],"descriptor":"Clear, relevant evaluation of the effect on the reader; clear understanding of the writer''s methods; clear response to the statement; relevant references."},{"level":2,"marks":[6,10],"descriptor":"Some evaluative comments on the effect on the reader; some understanding of methods; some response to the statement; some appropriate references."},{"level":1,"marks":[1,5],"descriptor":"Simple evaluative comments; limited understanding of methods; simple response to the statement; simple references."}],"indicative":["Sensory detail (''floor polish and somebody else''s lunch'') makes the place feel unfamiliar and not his","Downcast eyes ''on the lino'' and ''trainers that weren''t his'' show shyness and not belonging","Simile ''rose and broke like a wave'' suggests the noise is overwhelming, as if he might be swept away","''Everyone seemed to know exactly where they were going'' contrasts others'' confidence with his confusion","The illogical room numbers (11 then 22) add a touch of humour and frustration","Short sentences ''Nothing came out. His face burned.'' show his panic and embarrassment physically","The girl''s dialogue is short and casual; her confession ''I cried on my first day'' builds a connection","''the corridor seemed, very slightly, to shrink'' uses the setting to show his fear easing; ''very slightly'' suggests the change is small, so ''changes everything'' may be an overstatement","Evaluation of the extent of agreement, e.g. agree about nervousness but the change is gradual rather than complete"],"guidance":"Top-level answers engage critically with the statement, including its wording (''changes everything''), rather than simply agreeing."}'::jsonb, '{"AO4":20}'::jsonb, 0 from q;

with v(qt) as (select 'Both sources below were written for this question.

Source A (a modern blog post): "Our school day starts at 8.40 and finishes at 3.20. Most of us get the bus, and by the time I''m home I''ve got an hour of homework before tea. Clubs are optional, and loads of people do sport or drama. We have a forty-minute lunch break, which is never long enough when the queue goes past the hall doors."

Source B (written in the style of a letter from 1870, by a boy at a boarding school): "We rise at six by the bell and wash in cold water, for there is no other. Prayers, then Latin until breakfast, which is bread and weak tea. Lessons continue until four, save for half an hour at noon. In the evening we write our exercises by candlelight under the eye of the master, and woe betide any boy caught talking. I have not been home since Michaelmas."

You need to refer to Source A and Source B for this question.

The students in the two sources have different experiences of the school day. Use details from both sources to write a summary of the differences.

[8 marks]'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'compare', 8, 'foundation', 'AQA', 'L4.1', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Language' and t.name = 'Paper 2 Reading: Viewpoints and Perspectives' and st.name = 'Questions 1 and 2: true statements and summary'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":4,"marks":[7,8],"descriptor":"Perceptive synthesis and interpretation of both texts; judicious references; perceptive differences between the students'' experiences."},{"level":3,"marks":[5,6],"descriptor":"Clear synthesis and relevant interpretation; relevant references from both texts; clear statements of difference."},{"level":2,"marks":[3,4],"descriptor":"Some interpretation from one or both texts; some appropriate references; some difference identified."},{"level":1,"marks":[1,2],"descriptor":"Simple awareness of differences; simple references or paraphrase."}],"indicative":["Length of day: A starts at 8.40 and ends 3.20; B rises at six and lessons run until four, suggesting a far longer, harsher day","Home: A goes home every day on the bus; B is a boarder who ''has not been home since Michaelmas'', suggesting loneliness and separation","Freedom: A''s clubs are ''optional'' and lots of choice; B''s day is controlled by the bell and the master, suggesting strict discipline","Comfort: B washes in cold water and works by candlelight, inferring hardship; A''s complaints (lunch queue) are minor","Food: B has ''bread and weak tea''; A complains only about the queue, implying plenty of food","Tone: A is relaxed and conversational; B''s ''woe betide'' suggests fear of punishment"],"guidance":"This question tests inference and synthesis, not language analysis. Level 3+ needs inferences about both sources, not just copied facts."}'::jsonb, '{"AO1":8}'::jsonb, 0 from q;

with v(qt) as (select 'This source was written for this question, in the style of an 1890s newspaper report on a new invention.

"Never before has the public been offered so wondrous a machine as the motor-car now exhibited at the Crystal Palace. It glides along without horse or harness, puffing modestly, at a speed that would shame a galloping hunter. Ladies gasped; gentlemen removed their hats in astonishment. Yet I confess a creeping dread. What shall become of our quiet lanes when every reckless young fellow may roar through them at twelve miles an hour? What of the poor horse, the farrier, the coachman? Progress, it seems, is a hungry beast, and it will not ask our permission before it eats."

How does the writer use language to present his feelings about the motor-car?

[12 marks]'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'analyse', 12, 'higher', 'AQA', 'L4.2', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Language' and t.name = 'Paper 2 Reading: Viewpoints and Perspectives' and st.name = 'Question 3: language'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":4,"marks":[10,12],"descriptor":"Perceptive, detailed analysis of the effects of language; judicious quotations; sophisticated and accurate subject terminology."},{"level":3,"marks":[7,9],"descriptor":"Clear explanation of the effects of language; relevant quotations; clear and accurate terminology."},{"level":2,"marks":[4,6],"descriptor":"Some attempt to comment on the effect of language; some appropriate references; some terminology."},{"level":1,"marks":[1,3],"descriptor":"Simple comments on the effect of language; simple references."}],"indicative":["Superlative/hyperbole ''Never before... so wondrous'' shows initial amazement","''glides'' and ''puffing modestly'' make the car seem gentle and harmless at first","Comparison ''would shame a galloping hunter'' emphasises its speed with admiration","Crowd reactions ''Ladies gasped; gentlemen removed their hats'' show public wonder","''Yet'' marks a shift (volta) to anxiety: ''a creeping dread''","Rhetorical questions show worry about the effect on lanes, horses and jobs","''reckless young fellow may roar'' contrasts with ''glides'', showing danger and noise","Extended metaphor ''Progress... is a hungry beast'' presents change as unstoppable and destructive","Mixed feelings: admiration combined with fear; first-person ''I confess'' gives a personal, honest tone"],"guidance":"Level 3+ should recognise that the writer''s feelings change or are mixed."}'::jsonb, '{"AO2":12}'::jsonb, 0 from q;

with v(qt) as (select 'Both sources were written for this question.

Source A (a modern opinion article): "Smartphones have handed young people the world. A teenager can learn a language, start a business or organise a protest from their bedroom. Yes, there are dangers, but the panic from adults is nothing new: they said the same about television, and about the novel before that. Instead of banning phones, we should teach young people to use them wisely."

Source B (written in the style of an 1850s magazine article about novels): "I view with the gravest alarm the craze for cheap novels among the young. Girls sit up half the night devouring these tales of murder and romance, and come down to breakfast pale, idle and full of foolish notions. Their minds, which ought to be strengthened by improving books, are softened like wax. Parents must remove such poison from the house."

Compare how the two writers convey their different perspectives on young people and new forms of entertainment.

In your answer, you could:
• compare their different perspectives
• compare the methods the writers use to convey their perspectives
• support your response with references to both texts.

[16 marks]'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'compare', 16, 'higher', 'AQA', 'L4.3', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Language' and t.name = 'Paper 2 Reading: Viewpoints and Perspectives' and st.name = 'Question 4: comparing perspectives'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":4,"marks":[13,16],"descriptor":"Compares ideas and perspectives in a perceptive way; analyses how methods convey perspectives; judicious references to both texts."},{"level":3,"marks":[9,12],"descriptor":"Compares ideas and perspectives in a clear and relevant way; explains clearly how methods convey them; relevant references to both texts."},{"level":2,"marks":[5,8],"descriptor":"Attempts to compare ideas and perspectives; some comment on methods; some references from one or both texts."},{"level":1,"marks":[1,4],"descriptor":"Simple awareness of ideas and perspectives; simple identification of methods; simple references."}],"indicative":["A is positive and trusting of young people; B is alarmed and sees them as weak and easily corrupted","A: ''handed young people the world'' is a hyperbolic metaphor of opportunity; B: ''devouring'' and ''poison'' present entertainment as dangerous","A uses a list of positive possibilities (language, business, protest); B lists negative effects (''pale, idle and full of foolish notions'')","A concedes (''Yes, there are dangers'') to appear balanced; B is absolute (''gravest alarm'')","A uses historical comparison to dismiss moral panic, which ironically includes the kind of fear seen in B","B''s simile ''softened like wax'' suggests minds being shaped by bad influences","Solutions differ: A wants education (''teach young people''); B wants banning (''remove such poison'')","Tone: A is conversational and reasonable; B is formal, moralising and authoritative"],"guidance":"Level 3+ needs comparison of methods as well as perspectives, using both sources."}'::jsonb, '{"AO3":16}'::jsonb, 0 from q;

with v(qt) as (select 'You are going to enter a creative writing competition run by your local library.

Write a description of a busy market as it closes at the end of the day.

(24 marks for content and organisation, 16 marks for technical accuracy)

[40 marks]'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'describe', 40, 'higher', 'AQA', 'L5.1', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Language' and t.name = 'Writing' and st.name = 'Paper 1 Question 5: descriptive and narrative writing'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":4,"marks":[19,24],"descriptor":"Compelling, convincing communication. Register convincingly matched to purpose; extensive, ambitious vocabulary; a range of conscious, crafted linguistic devices. Organisation: varied and inventive structural features; fluently linked paragraphs with seamlessly integrated discourse markers."},{"level":3,"marks":[13,18],"descriptor":"Consistent, clear communication. Register consistently matched to purpose; increasingly sophisticated vocabulary; a range of linguistic devices used successfully. Organisation: effective structural features; coherent paragraphs with integrated discourse markers."},{"level":2,"marks":[7,12],"descriptor":"Some sustained communication. Some attempt to match register; vocabulary chosen for effect; some linguistic devices. Organisation: some structural features; some paragraphs, some discourse markers."},{"level":1,"marks":[1,6],"descriptor":"Simple communication. Simple awareness of register; simple vocabulary and devices. Organisation: evidence of simple structural features; random or unlinked paragraphs."}],"indicative":["Writes a description, not a story; any narrative is minimal and serves the description","Sensory detail: the smell of bruised fruit, the clatter of dismantled stalls, cold air as the light fades","A shift in atmosphere from busy to empty, e.g. structured around time passing","Zooming in on small details (a lost glove, a pigeon pecking at crumbs) and back out to the whole scene","Figurative language, varied sentence forms and an ending that links back to the opening"],"guidance":"Content and organisation are marked out of 24 using the levels. A narrative with little description should not go above Level 2 for content.","spag":"AO6 technical accuracy, out of 16, marked separately: 13-16 = sentence demarcation consistently secure and accurate; wide range of punctuation used with a high level of accuracy; full range of sentence forms for effect; Standard English used consistently with secure control of complex grammar; high level of accuracy in spelling including ambitious vocabulary; extensive and ambitious vocabulary. 9-12 = sentence demarcation mostly secure; range of punctuation mostly accurate; variety of sentence forms for effect; Standard English mostly controlled; generally accurate spelling including complex words; increasingly sophisticated vocabulary. 5-8 = sentence demarcation mostly secure and sometimes accurate; some control of a range of punctuation; attempts a variety of sentence forms; some use of Standard English; some accurate spelling of more complex words; varied vocabulary. 1-4 = occasional sentence demarcation; some evidence of conscious punctuation; simple sentence forms; occasional Standard English; accurate basic spelling; simple vocabulary. 0 = no evidence of these skills."}'::jsonb, '{"AO5":24,"AO6":16}'::jsonb, 16 from q;

with v(qt) as (select '"Mobile phones should be banned from school completely. They do far more harm than good."

