insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":4,"marks":[19,24],"descriptor":"Compelling, convincing communication. Register, tone and style convincingly matched to a broadsheet article and to arguing; extensive, ambitious vocabulary; crafted rhetorical devices. Organisation: varied and inventive structure; highly structured and developed ideas, complex and connected; fluently linked paragraphs."},{"level":3,"marks":[13,18],"descriptor":"Consistent, clear communication. Register consistently matched to purpose and audience; increasingly sophisticated vocabulary; a range of successful devices. Organisation: effective structure; engaging, connected ideas; coherent paragraphs with integrated discourse markers."},{"level":2,"marks":[7,12],"descriptor":"Some sustained communication. Some attempt to match register to purpose and audience; vocabulary chosen for effect; some devices. Organisation: some structural features; increasingly varied and linked ideas; some paragraphs and discourse markers."},{"level":1,"marks":[1,6],"descriptor":"Simple communication. Simple awareness of purpose and audience; simple vocabulary and devices. Organisation: simple structural features; one or two relevant ideas, simply linked; random paragraphing."}],"indicative":["A clear position sustained throughout (for or against, or a nuanced position)","Article conventions: a headline, possibly a strapline, an engaging opening, a formal but lively broadsheet register","Arguments, e.g. distraction and cyberbullying versus safety, learning tools and teaching responsible use","Counter-argument acknowledged and rebutted","Rhetorical devices: rhetorical questions, statistics or expert opinion, anecdote, direct address, rule of three","A strong conclusion, e.g. a call to action or a link back to the opening"],"guidance":"Content and organisation are marked out of 24 using the levels. Writing that does not argue a view, or ignores the article form, should not go above Level 2 for content.","spag":"AO6 technical accuracy, out of 16, marked separately: 13-16 = sentence demarcation consistently secure and accurate; wide range of punctuation used with a high level of accuracy; full range of sentence forms for effect; Standard English used consistently with secure control of complex grammar; high level of accuracy in spelling including ambitious vocabulary; extensive and ambitious vocabulary. 9-12 = sentence demarcation mostly secure; range of punctuation mostly accurate; variety of sentence forms for effect; Standard English mostly controlled; generally accurate spelling including complex words; increasingly sophisticated vocabulary. 5-8 = sentence demarcation mostly secure and sometimes accurate; some control of a range of punctuation; attempts a variety of sentence forms; some use of Standard English; some accurate spelling of more complex words; varied vocabulary. 1-4 = occasional sentence demarcation; some evidence of conscious punctuation; simple sentence forms; occasional Standard English; accurate basic spelling; simple vocabulary. 0 = no evidence of these skills."}'::jsonb, '{"AO5":24,"AO6":16}'::jsonb, 16 from q;

with v(qt) as (select 'This paragraph from a student''s letter to a headteacher contains six errors in spelling, punctuation or grammar.

"Their are many reasons why the school should of kept the library open at lunch. Students who doesn''t have computers at home needs somewhere to work, the library is also a quiet place for people who find the playground stressfull."

Find and correct the six errors. You can rewrite the paragraph, or list each error with its correction.'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'determine', 6, 'foundation', 'AQA', 'L6.3', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Language' and t.name = 'Technical Accuracy' and st.name = 'Grammar and Standard English'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'points', '{"max":6,"points":["''Their'' corrected to ''There''","''should of'' corrected to ''should have''","''doesn''t'' corrected to ''don''t'' (agreement with plural ''Students'')","''needs'' corrected to ''need'' (agreement with plural ''Students'')","Comma splice fixed: full stop or semicolon before ''the library'' (or a conjunction added)","''stressfull'' corrected to ''stressful''"],"guidance":"One mark per error correctly fixed. Accept any correct fix for the comma splice (full stop, semicolon, or a conjunction such as ''and''). Do not award a mark if the fix introduces a new error."}'::jsonb, '{"AO6":6}'::jsonb, 0 from q;

commit;
